using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
// Incomplete editor work only. Never a hypothesis, approval, execution receipt, or customer evidence.
public static class ManualDraftRecovery {
 public const string Folder="manual-editor-recovery";
 public sealed class Draft {public string Id,Hash;public Dictionary<string,object>Data;}
 static readonly string[] Keys={"title","interpretation","assumptions","buyer_role","next_action","success","failure"};
 static string PathFor(string root,string id){if(!System.Text.RegularExpressions.Regex.IsMatch(id??"","^[0-9a-f]{32}$"))throw new InvalidDataException("Invalid editor draft identity");return Path.Combine(root,Folder,id+".json");}
 public static void Validate(Dictionary<string,object>d){
  if(ManualHypotheses.S(d,"schema")!="reveng-editor-recovery-v1"||ManualHypotheses.S(d,"status")!="INCOMPLETE_EDITOR_WORK_NOT_HYPOTHESIS"||!(ManualHypotheses.V(d,"auto_admission") is bool)|| (bool)d["auto_admission"])throw new InvalidDataException("Invalid recovery policy");
  if(d.Count!=9||d.Keys.Except(new[]{"schema","status","auto_admission","saved_at","source_snapshot","previous_id","start","end","fields"}).Any())throw new InvalidDataException("Unexpected recovery property");string previous=ManualHypotheses.S(d,"previous_id");if(previous!=""&&!System.Text.RegularExpressions.Regex.IsMatch(previous,"^[0-9a-f]{64}$"))throw new InvalidDataException("Invalid previous note");var s=ManualHypotheses.D(ManualHypotheses.V(d,"source_snapshot"));string text=ManualHypotheses.S(s,"text");if(ProvenanceAudit.Sha(text)!=ManualHypotheses.S(s,"text_sha256"))throw new InvalidDataException("Recovery source snapshot mismatch");
  var f=ManualHypotheses.D(ManualHypotheses.V(d,"fields"));if(f.Count!=Keys.Length||Keys.Any(k=>!f.ContainsKey(k)||!(f[k] is string)||((string)f[k]).Length>(k=="title"?200:4000)))throw new InvalidDataException("Invalid recovery editor fields");
  object a=ManualHypotheses.V(d,"start"),b=ManualHypotheses.V(d,"end");if(!(a is int)||!(b is int))throw new InvalidDataException("Invalid recovery range");int start=(int)a,end=(int)b;if(!(start==-1&&end==-1)&&(start<0||end<=start||end>ProvenanceAudit.Count(text)||end-start>1000))throw new InvalidDataException("Invalid recovery range");
 }
 public static List<Draft> Load(string root,out string error){var result=new List<Draft>();var errors=new List<string>();string folder=Path.Combine(root,Folder);if(Directory.Exists(folder))foreach(string path in Directory.GetFiles(folder,"*.json").OrderBy(x=>x)){try{string id=Path.GetFileNameWithoutExtension(path);PathFor(root,id);if(new FileInfo(path).Length>1048576)throw new InvalidDataException("Recovery exceeds1MiB");string raw=LocalJson.ReadText(path,1048576);var wrap=LocalJson.ParseObject(raw);string payload=ManualHypotheses.S(wrap,"payload_json");if(ProvenanceAudit.Sha(payload)!=ManualHypotheses.S(wrap,"payload_sha256"))throw new InvalidDataException("Recovery payload hash mismatch");var d=LocalJson.ParseObject(payload);Validate(d);result.Add(new Draft{Id=id,Hash=ProvenanceAudit.Sha(raw),Data=d});}catch(Exception ex){errors.Add(Path.GetFileName(path)+": "+ex.Message);}}error=String.Join("; ",errors);return result;}
 public static string Save(string root,string id,Dictionary<string,object>d,string expected){ManualHypotheses.RequireWritable(root);Validate(d);string path=PathFor(root,id),folder=Path.GetDirectoryName(path);Directory.CreateDirectory(folder);using(var gate=new FileStream(Path.Combine(Path.GetDirectoryName(path),"active.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){if(!File.Exists(path)&&Directory.GetFiles(folder,"*.json").Length>=20)throw new InvalidDataException("20 incomplete drafts retained; finish or discard an existing draft first");string payload=ManualHypotheses.Serialize(d),raw=ManualHypotheses.Serialize(new Dictionary<string,object>{{"payload_json",payload},{"payload_sha256",ProvenanceAudit.Sha(payload)}});if(Encoding.UTF8.GetByteCount(raw)>1048576)throw new InvalidDataException("Recovery exceeds1MiB");if(File.Exists(path)&&ProvenanceAudit.Sha(LocalJson.ReadText(path,1048576))!=expected||!File.Exists(path)&&expected!="")throw new InvalidDataException("Recovery changed in another editor; existing work preserved");if(File.Exists(path)){string error;var old=Load(root,out error).FirstOrDefault(x=>x.Id==id);if(old==null)throw new InvalidDataException("Existing recovery damaged; bytes preserved");}string temp=LocalJson.TemporaryPath(path);try{LocalJson.WriteTemporary(temp,raw);if(File.Exists(path))File.Replace(temp,path,LocalJson.BackupPath(path));else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}return ProvenanceAudit.Sha(raw);}}
 public static void Remove(string root,string id,string expected){ManualHypotheses.RequireWritable(root);string path=PathFor(root,id);using(var gate=new FileStream(Path.Combine(Path.GetDirectoryName(path),"active.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){if(File.Exists(path)){if(ProvenanceAudit.Sha(LocalJson.ReadText(path,1048576))!=expected)throw new InvalidDataException("Newer recovery preserved");File.Delete(path);}if(File.Exists(path+".previous"))File.Delete(path+".previous");if(File.Exists(LocalJson.BackupPath(path)))File.Delete(LocalJson.BackupPath(path));}}
}
